package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DpopBoundAccessTokensVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dpop bound access tokens of oauth client ")
  void test_dpop_bound_access_tokens_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> DpopBoundAccessTokensVO.tryFrom(null));
    Assertions.assertEquals(true, DpopBoundAccessTokensVO.from(true).isDpopBoundAccessTokens());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DpopBoundAccessTokensVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", DpopBoundAccessTokensVO.from(true).toString());
  }
}
